import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonReader_nextInt_TriageGen2Test {











    @Test(expected = NumberFormatException.class)
    public void testNextInt_PrecisionLoss_LongToInt() throws IOException {
        // Testing the precision loss check: (int) peekedLong != peekedLong
        // We use a value larger than Integer.MAX_VALUE
        String json = "2147483648"; 
        JsonReader reader = new JsonReader(new StringReader(json));
        reader.nextInt(); // This should throw NumberFormatException
    }










}

