public class JsonReader_nextInt_TriageGen2Test {

















    @Test(expected = IllegalStateException.class)
    public void testNextInt_WrongToken() throws IOException {
        String json = "{\"key\": 1}";
        JsonReader reader = new JsonReader(new StringReader(json));
        reader.beginObject();
        reader.nextName();
        reader.nextInt(); // This should fail because we are at a value, but the logic depends on peek()
    }




}

